{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Asciminib, the highest-transfer analogue, has an absolute oral bioavailability of approximately 73% in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Levofloxacin, a structurally related heteroaromatic drug, shows an absolute oral bioavailability of approximately 99% after a 500 mg oral dose, strongly supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pradigastat, a carboxylic acid-containing biaryl drug, has an absolute oral bioavailability of about 40% in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Even the least favorable retrieved analogue, with 34% oral bioavailability in fasted healthy volunteers, exceeds the 20% threshold; no retrieved evidence indicates F < 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved high-transfer experimental analogues show oral bioavailability values from 34% to ~100%, all above the 20% threshold. The query's phosphate group introduces physicochemical uncertainty, but there is no affirmative evidence for low bioavailability, so the prediction is high.",
  "evidence_gaps": [
    "No retrieved analogue contains a phosphate ester or phosphonic acid group, so the effect of the query's ionizable phosphate on oral absorption is not directly evidenced.",
    "No human absolute oral bioavailability data exist for the query molecule itself.",
    "No direct information is available on intestinal phosphate cleavage, permeability, or transporter involvement for this specific scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

